namespace WildBoundGarage {
public static class Data {
 public static readonly JavaScriptSerializer Json=new JavaScriptSerializer { MaxJsonLength=48000000, RecursionLimit=120 };
 public static Dictionary<string,object> Obj(object x){return x as Dictionary<string,object> ?? new Dictionary<string,object>();}
 public static object Get(object x,string key){object v;return Obj(x).TryGetValue(key,out v)?v:null;}
 public static string Text(object x,string key){return Convert.ToString(Get(x,key),CultureInfo.InvariantCulture)??"";}
 public static object[] Items(object x){return x as object[] ?? (x as ArrayList == null ? new object[0] : ((ArrayList)x).ToArray());}
 public static double Num(object x){return x==null?0:Convert.ToDouble(x,CultureInfo.InvariantCulture);}
 public static object Read(string file){return Json.DeserializeObject(File.ReadAllText(file));}
}
public class JobRow {
 public string Id,Title,Status,Kind;public object Value;
 public override string ToString(){return Title+"\n"+Status.Replace('_',' ')+"  ·  "+Kind;}
}
public class AssetKindOption {
 public string Value {get;set;} public string Label {get;set;}
 public AssetKindOption(string value,string label){Value=value;Label=label;}
}
