 void SetView(string next){view=next;body.Children.Clear();teamPanel=null;if(view=="Production"||view=="Asset Studio"){composer.Visibility=view=="Production"?Visibility.Visible:Visibility.Collapsed;body.Children.Add(workspace);subtitle.Text=view=="Production"?"One prompt. Specialist workers. Reviewed assets delivered to Unreal.":"Inspect generated media and supplied models, then send approved assets into Unreal.";jobFingerprint="";RenderList();}else{teamPanel=new StackPanel();body.Children.Add(new ScrollViewer{Content=teamPanel,VerticalScrollBarVisibility=ScrollBarVisibility.Auto});RenderInfo();}}
 void RenderInfo(){if(teamPanel==null)return;teamPanel.Children.Clear();if(view=="Autopilot"){RenderAutopilot();}else if(view=="AI Team"){
  subtitle.Text="Specialist AI roles and tool workers share one queue, context, and artifact record.";
  foreach(var agent in Data.Items(Data.Get(status,"teams"))){var p=new StackPanel();p.Children.Add(T(Data.Text(agent,"name"),19));p.Children.Add(T(Data.Text(agent,"engine"),12,accent));p.Children.Add(T(Data.Text(agent,"role"),14,muted));var c=Card(p);c.Margin=new Thickness(0,0,0,12);teamPanel.Children.Add(c);}
 }else{subtitle.Text="Local installation and production capabilities.";var p=new StackPanel();p.Children.Add(T("Connected workspace",20));p.Children.Add(T(Data.Text(config,"repoRoot"),14,accent));p.Children.Add(T("Native Windows interface · local worker service · authenticated loopback connection",13,muted));p.Children.Add(T("Local model: "+Data.Text(config,"model")+"\nBlender: "+Data.Text(status,"blenderAvailable")+"\nUnreal: "+Data.Text(status,"unrealAvailable"),14));foreach(var x in Data.Items(Data.Get(status,"limits")))p.Children.Add(T("• "+Convert.ToString(x),13,muted));p.Children.Add(Button("Open local configuration",()=>Process.Start("notepad.exe",Quote(Path.Combine(root,"garage.config.json")))));p.Children.Add(T("Configuration changes take effect after restarting the Garage. Generated source files, task history, and review records live in Garage/runtime/jobs. No publish or Git push occurs from this program.",12,muted));teamPanel.Children.Add(Card(p));}}
 void RenderAutopilot(){
  subtitle.Text="Bounded local workflows run once, save every step, and stop on failure.";var manager=Data.Get(status,"localManager");if(manager==null){teamPanel.Children.Add(Card(T("The Local Autopilot is unavailable.",14,muted)));return;}
  var active=Data.Get(manager,"active");var intro=new StackPanel();intro.Children.Add(T("Supervised Local Autopilot",22));intro.Children.Add(T(active==null?"READY · allowlisted actions only":"WORKING · "+Data.Text(active,"name")+(Data.Text(active,"currentStep")==""?"":"\nCurrent step: "+Data.Text(active,"currentStep")),13,active==null?accent:ink));intro.Children.Add(T("No arbitrary commands. No automatic retries. Completed workflow steps remain in the audit record if the Garage closes.",12,muted));teamPanel.Children.Add(Card(intro));
  foreach(var action in Data.Items(Data.Get(manager,"actions"))){var p=new StackPanel();var workflow=Data.Text(action,"workflow")=="True";var needsApproval=Data.Text(action,"approvalRequired")=="True";var actionState=Data.Text(action,"state");p.Children.Add(T(actionState=="blocked"?"BLOCKED":needsApproval?"APPROVAL":workflow?"AUTOPILOT":"LOCAL",10,accent));p.Children.Add(T(Data.Text(action,"name"),18));var detail=Data.Text(action,"detail");var actionSteps=Data.Items(Data.Get(action,"steps"));if(actionSteps.Length>0)detail+=(detail==""?"":"\n")+"Steps: "+String.Join(" → ",actionSteps.Select(x=>Data.Text(x,"name")));p.Children.Add(T(detail,12,muted));var selected=action;p.Children.Add(Button(needsApproval?"Approve & run":workflow?"Run one pass":Data.Text(action,"id")=="metahuman-foundation-preflight"?"Verify again":"Run locally",()=>Guard(()=>RunManager(selected)),workflow));var card=Card(p);card.Margin=new Thickness(0,12,0,0);teamPanel.Children.Add(card);}
  var history=Data.Items(Data.Get(manager,"history"));if(history.Length>0){teamPanel.Children.Add(T("\nRECENT LOCAL WORK",10,accent));foreach(var item in history.Take(5)){var itemSteps=Data.Items(Data.Get(item,"steps"));var progress=itemSteps.Length>0?" · "+itemSteps.Count(x=>Data.Text(x,"status")=="completed")+"/"+itemSteps.Length+" steps":"";var resultLines=new List<string>();foreach(var itemStep in itemSteps){var summary=Data.Get(Data.Get(itemStep,"result"),"summary");if(summary==null)continue;if(Data.Text(itemStep,"actionId")=="asset-artifact-readiness")resultLines.Add(Data.Text(summary,"verifiedChecksums")+"/"+Data.Text(summary,"artifactCount")+" artifact checksums · "+Data.Text(summary,"readyForReview")+" ready for review · "+Data.Text(summary,"issueCount")+" issues");if(Data.Text(itemStep,"actionId")=="asset-reference-readiness")resultLines.Add(Data.Text(summary,"verifiedArchiveObjects")+" archive originals · "+Data.Text(summary,"pinnedReferences")+" pinned references · "+Data.Text(summary,"issueCount")+" issues");}teamPanel.Children.Add(T(Data.Text(item,"name")+" · "+Data.Text(item,"status").ToUpperInvariant()+progress+(resultLines.Count>0?"\n"+String.Join(" · ",resultLines):""),12,muted));}}
 }
 async Task RunManager(object action){var id=Data.Text(action,"id");var approval=Data.Text(action,"approvalRequired")=="True";if(approval&&MessageBox.Show(this,"Approve this predefined local write action? Its destination is fixed and the result will be audited.","Local Autopilot",MessageBoxButton.YesNo,MessageBoxImage.Question)!=MessageBoxResult.Yes)return;var result=await Api("/local-manager/run",new{actionId=id,dryRun=false,confirmation=approval?id:null});await Refresh();MessageBox.Show(this,Data.Text(result,"name")+": "+Data.Text(result,"status"),"Local Autopilot",MessageBoxButton.OK,Data.Text(result,"status")=="completed"?MessageBoxImage.Information:MessageBoxImage.Warning);}
 void PickSource(){var d=new OpenFileDialog{Filter="3D models|*.glb;*.fbx",Title="Choose an approved model source"};if(d.ShowDialog(this)==true){sourcePath=d.FileName;sourceLabel.Text=sourcePath;if(!new[]{"model","rigging","animation"}.Contains(Convert.ToString(kind.SelectedValue)))kind.SelectedValue="model";}}
 void ApplyKindOptions(object capabilities){var specs=new[]{new AssetKindOption("auto","Automatic · let Director choose"),new AssetKindOption("concept-art","2D concept art"),new AssetKindOption("texture","Texture / material"),new AssetKindOption("skybox","Skybox source image"),new AssetKindOption("vfx-source","VFX source artwork"),new AssetKindOption("voice","Character voice"),new AssetKindOption("music","Music"),new AssetKindOption("ambience","Musical ambience"),new AssetKindOption("sfx","Isolated sound effect"),new AssetKindOption("text-to-3d","3D static prop"),new AssetKindOption("model","Prepare supplied 3D model"),new AssetKindOption("rigging","Inspect supplied rig"),new AssetKindOption("animation","Inspect supplied animation")};var selected=Convert.ToString(kind==null?null:kind.SelectedValue);var available=Data.Items(capabilities).Where(item=>Convert.ToBoolean(Data.Get(item,"available"),CultureInfo.InvariantCulture)).Select(item=>Data.Text(item,"id")).ToHashSet(StringComparer.Ordinal);var mapping=new Dictionary<string,string>{{"concept-art","concept-art"},{"texture","image"},{"skybox","skybox"},{"vfx-source","vfx-source"},{"voice","voice"},{"music","audio"},{"ambience","audio"},{"sfx","sfx"},{"text-to-3d","text-to-3d"},{"model","model"},{"rigging","rigging"},{"animation","animation"}};kind.ItemsSource=capabilities==null?specs:specs.Where(option=>option.Value=="auto"||(mapping.ContainsKey(option.Value)&&available.Contains(mapping[option.Value]))).ToArray();kind.SelectedValue=specs.Any(option=>option.Value==selected)&&kind.Items.Cast<AssetKindOption>().Any(option=>option.Value==selected)?selected:"auto";}
 async Task CreateJob(){if(starting)throw new Exception("Workers are still starting.");var result=await Api("/jobs",new{prompt=prompt.Text,kind=Convert.ToString(kind.SelectedValue),biome=Convert.ToString(biome.SelectedItem),voice=Convert.ToString(voice.SelectedItem),sourcePath=String.IsNullOrEmpty(sourcePath)?null:sourcePath});selectedId=Data.Text(result,"id");prompt.Text="";sourcePath="";sourceLabel.Text="Task accepted. The team will return an artifact for review.";await Refresh();}
 async void Guard(Func<Task> task){try{await task();}catch(Exception e){MessageBox.Show(this,e.Message,"AI Garage",MessageBoxButton.OK,MessageBoxImage.Information);}}
 async Task<object> Api(string path,object data=null){using(var req=new HttpRequestMessage(data==null?HttpMethod.Get:HttpMethod.Post,baseUrl+path)){req.Headers.Authorization=new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer",token);if(data!=null)req.Content=new StringContent(Data.Json.Serialize(data),Encoding.UTF8,"application/json");using(var response=await http.SendAsync(req)){var result=Data.Json.DeserializeObject(await response.Content.ReadAsStringAsync());if(!response.IsSuccessStatusCode)throw new Exception(Data.Text(result,"error"));return result;}}}
 static string Quote(string s){return "\""+s.Replace("\"","")+"\"";}
 void Worker(string exe,string args,string cwd){var info=new ProcessStartInfo(exe,args){UseShellExecute=false,CreateNoWindow=true,WorkingDirectory=cwd};Process.Start(info);}
 async Task Start(){try{
  config=Data.Read(Path.Combine(root,"garage.config.json"));baseUrl="http://127.0.0.1:"+Data.Text(config,"port");http.Timeout=TimeSpan.FromSeconds(25);var dashboard=Data.Text(config,"dashboardRoot");
  Worker("powershell.exe","-NoProfile -NonInteractive -ExecutionPolicy Bypass -WindowStyle Hidden -File "+Quote(Path.Combine(dashboard,"Start-WildBoundLocalAI.ps1"))+" -NoOpenUI",dashboard);
  var tokenFile=Path.Combine(dashboard,"runtime","control-token.txt");for(int i=0;i<90&&!File.Exists(tokenFile);i++)await Task.Delay(1000);token=File.ReadAllText(tokenFile).Trim();
  bool live=false;try{await Api("/jobs");live=true;}catch{}
  if(!live)Worker(Path.Combine(dashboard,"..","Tools","node.exe"),Quote(Path.Combine(root,"src","service.js")),root);
  for(int i=0;i<60;i++){try{await Api("/jobs");live=true;break;}catch{}await Task.Delay(1000);}
  if(!live)throw new Exception("Production service did not start. Check the local configuration and worker files.");
  starting=false;await Refresh();timer=new DispatcherTimer{Interval=TimeSpan.FromSeconds(3)};timer.Tick+=async(s,e)=>await Refresh();timer.Start();
 }catch(Exception e){connection.Text="Startup needs attention";detailError.Text=e.Message;}}
 int ticks=0;
 async Task Refresh(){if(refreshing||closing||starting)return;refreshing=true;try{
  var data=await Api("/jobs");jobs.Clear();foreach(var value in Data.Items(Data.Get(data,"jobs"))){var brief=Data.Get(value,"brief");jobs.Add(new JobRow{Id=Data.Text(value,"id"),Title=String.IsNullOrEmpty(Data.Text(brief,"name"))?Data.Text(value,"prompt").Substring(0,Math.Min(70,Data.Text(value,"prompt").Length)):Data.Text(brief,"name"),Kind=Data.Text(brief,"kind")==""?Data.Text(value,"kind"):Data.Text(brief,"kind"),Status=Data.Text(value,"status"),Value=value});}
  RenderList();var current=jobs.Find(j=>j.Id==selectedId);if(current!=null)RenderJob(current.Value);
  if(status==null||ticks++%5==0){status=await Api("/status");ApplyKindOptions(Data.Get(status,"capabilities"));RenderInfo();}connection.Text="Workers connected · "+Data.Num(Data.Get(status,"freeRamGiB")).ToString("0.0")+" GiB free";
  // Keep the legacy worker lifetime monitor aware of the native window.
  using(var heartbeat=new HttpRequestMessage(HttpMethod.Post,"http://127.0.0.1:8765/api/garage-heartbeat")){heartbeat.Headers.Add("Origin","http://127.0.0.1:8765");heartbeat.Content=new StringContent("{\"sentAt\":"+DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()+"}",Encoding.UTF8,"application/json");using(var response=await http.SendAsync(heartbeat)){} }
 }catch(Exception e){connection.Text="Worker connection needs attention";detailError.Text=e.Message;}finally{refreshing=false;}}
 void RenderList(){if(view!="Production"&&view!="Asset Studio")return;var visible=jobs.Where(j=>view!="Asset Studio"||Data.Get(j.Value,"artifact")!=null).ToList();var key=String.Join("|",visible.Select(j=>j.Id+j.Status+j.Title));if(key==jobFingerprint)return;jobFingerprint=key;jobList.ItemsSource=null;jobList.ItemsSource=visible;if(selectedId==""&&visible.Count>0)selectedId=visible[0].Id;jobList.SelectedItem=visible.Find(j=>j.Id==selectedId);}
 void RenderJob(object j){
  var brief=Data.Get(j,"brief");var state=Data.Text(j,"status");detailTitle.Text=Data.Text(brief,"name")==""?"Preparing your brief…":Data.Text(brief,"name").Replace('_',' ');detailStatus.Text=state.Replace('_',' ').ToUpperInvariant()+"  ·  "+Data.Text(brief,"kind");detailError.Text=Data.Text(j,"error");
  steps.Children.Clear();int n=1;foreach(var step in Data.Items(Data.Get(j,"steps"))){var s=Data.Text(step,"status");steps.Children.Add(T(n++.ToString("00")+"  "+Data.Text(step,"name")+"\n      "+s.Replace('_',' '),12,s=="completed"?accent:s=="running"?ink:muted));}
  var artifact=Data.Get(j,"artifact");var checks=Data.Get(j,"checks");var engine=Data.Get(j,"engine");
  inspection.Text=artifact==null?Data.Text(brief,"summary"):DescribeChecks(checks,Data.Text(artifact,"kind"));
  var hasPlan=Data.Get(j,"characterDesign")!=null||Data.Get(j,"spec")!=null;if(hasPlan)inspection.Text+=Data.Text(brief,"kind")=="model"?"\nSpecialist production plan ready · open it below before attaching the source model.":"\nSpecialist production direction ready · open it below for review.";
  bool hasReferenceDetails=false;var referencePackage=Data.Get(j,"referencePackage");if(referencePackage!=null){var references=Data.Items(Data.Get(referencePackage,"references"));var missing=Data.Items(Data.Get(referencePackage,"missing"));var conflicts=Data.Items(Data.Get(referencePackage,"conflicts"));hasReferenceDetails=references.Length+missing.Length+conflicts.Length>0;if(hasReferenceDetails)inspection.Text+="\nReferences: "+references.Length+" approved version"+(references.Length==1?"":"s")+" · "+missing.Length+" missing · "+conflicts.Length+" conflicts";}
  var quality=Data.Get(j,"quality");if(quality!=null)inspection.Text+="\nQuality Supervisor: "+(Convert.ToBoolean(Data.Get(quality,"passed"),CultureInfo.InvariantCulture)?"PASSED":"REJECTED")+(Data.Items(Data.Get(quality,"issues")).Length==0?"":" · "+String.Join(" ",Data.Items(Data.Get(quality,"issues")).Select(Convert.ToString)));
  if(engine!=null)inspection.Text+="\nUnreal: "+String.Join(" · ",Data.Items(Data.Get(engine,"assets")).Select(a=>Data.Text(a,"class")));
  var use=Data.Items(Data.Get(j,"usage"));if(use.Length>0)inspection.Text+="\nLocal AI: "+use.Length+" role requests · "+use.Sum(u=>Data.Num(Data.Get(u,"promptTokens"))+Data.Num(Data.Get(u,"responseTokens"))).ToString("N0")+" reported tokens";
  previewCaption.Text=artifact==null?"":new[]{"model","text-to-3d","rigging","animation"}.Contains(Data.Text(artifact,"kind"))?"Native 3D viewport · left drag to orbit · mouse wheel to zoom · rest pose preview":"Generated locally. Review the output before importing it into Unreal.";
  string key=selectedId+Data.Text(artifact,"sha256");if(previewKey!=key){previewKey=key;LoadPreview(artifact,key);}
  actions.Children.Clear();string id=Data.Text(j,"id");if(state=="awaiting_review"){actions.Children.Add(Button("Approve & import",()=>Guard(async()=>{await Api("/jobs/"+id+"/approve",new{});await Refresh();}),true));actions.Children.Add(Button("Reject",()=>Guard(async()=>{await Api("/jobs/"+id+"/reject",new{});await Refresh();})));}
  if(state=="needs_source"&&Data.Get(j,"spec")==null)actions.Children.Add(Button("Prepare model plan",()=>Guard(async()=>{await Api("/jobs/"+id+"/prepare-plan",new{});await Refresh();}),true));
  if(hasPlan)actions.Children.Add(Button("View specialist plan",()=>MessageBox.Show(this,DescribePlan(j),"Specialist production plan",MessageBoxButton.OK,MessageBoxImage.Information)));
  if(hasReferenceDetails)actions.Children.Add(Button("View references",()=>MessageBox.Show(this,DescribeReferences(j),"Worker reference package",MessageBoxButton.OK,MessageBoxImage.Information)));
  if(state=="needs_source")actions.Children.Add(Button("Attach approved model",()=>Guard(async()=>{var d=new OpenFileDialog{Filter="3D models|*.glb;*.fbx"};if(d.ShowDialog(this)==true){await Api("/jobs/"+id+"/attach",new{sourcePath=d.FileName});await Refresh();}}),true));
  if((state=="failed"||state=="interrupted")&&Data.Get(j,"approvedAt")!=null)actions.Children.Add(Button("Retry engine import",()=>Guard(async()=>{await Api("/jobs/"+id+"/retry-import",new{});await Refresh();})));
  if(new[]{"running","queued","importing","needs_source"}.Contains(state))actions.Children.Add(Button("Cancel task",()=>Guard(async()=>{await Api("/jobs/"+id+"/cancel",new{});await Refresh();})));
  if(artifact!=null)actions.Children.Add(Button("Open files",()=>Process.Start("explorer.exe",Quote(Path.GetDirectoryName(Data.Text(artifact,"source"))))));
 }
 string DescribeChecks(object c,string kind){if(c==null)return "Inspecting production output…";if(new[]{"model","text-to-3d","rigging","animation"}.Contains(kind))return Data.Text(c,"triangles")+" triangles · "+Data.Text(c,"meshes")+" meshes · "+Data.Text(c,"armatures")+" armatures\nClips: "+String.Join(", ",Data.Items(Data.Get(c,"animations")).Select(Convert.ToString));if(new[]{"concept-art","texture","skybox","vfx-source"}.Contains(kind))return Data.Text(c,"width")+" × "+Data.Text(c,"height")+" · "+Data.Text(c,"format")+(kind=="texture"?" · Unreal texture + base-color material":" · image source art");return Data.Num(Data.Get(c,"seconds")).ToString("0.0")+" seconds · "+Data.Text(c,"sampleRate")+" Hz · "+Data.Text(c,"bitDepth")+" bit · "+Data.Text(c,"channels")+" channels";}
 string DescribePlan(object j){var design=Data.Get(j,"characterDesign");var plan=Data.Get(j,"spec");var text=new StringBuilder();if(design!=null){text.AppendLine("CHARACTER DESIGN");foreach(var field in new[]{"silhouette","anatomy","costume","materials","identity","notes"}){var value=Data.Text(design,field);if(!String.IsNullOrWhiteSpace(value))text.AppendLine("\n"+Char.ToUpperInvariant(field[0])+field.Substring(1)+":\n"+value);}}if(plan!=null){text.AppendLine("\n\n3D ARTIST HANDOFF");var intent=Data.Text(plan,"prompt");var notes=Data.Text(plan,"notes");if(!String.IsNullOrWhiteSpace(intent))text.AppendLine("\nIntent:\n"+intent);if(!String.IsNullOrWhiteSpace(notes))text.AppendLine("\nTechnical notes:\n"+notes);}return text.ToString().Trim();}
 string DescribeReferences(object j){var pack=Data.Get(j,"referencePackage");var text=new StringBuilder("PRODUCTION REQUIREMENTS");foreach(var item in Data.Items(Data.Get(Data.Get(j,"brief"),"requirements")))text.AppendLine("\n• "+Convert.ToString(item));var references=Data.Items(Data.Get(pack,"references"));text.AppendLine("\n\nAPPROVED VERSION-PINNED REFERENCES");if(references.Length==0)text.AppendLine("\nNone");foreach(var reference in references){text.AppendLine("\n"+Data.Text(reference,"id")+"@v"+Data.Text(reference,"version"));var coverage=Data.Items(Data.Get(reference,"coverage"));if(coverage.Length>0)text.AppendLine("Coverage: "+String.Join(", ",coverage.Select(Convert.ToString)));foreach(var media in Data.Items(Data.Get(reference,"media")))text.AppendLine(Data.Text(media,"kind")+" · "+Data.Text(media,"name")+"\nSHA-256 "+Data.Text(media,"sha256"));}var missing=Data.Items(Data.Get(pack,"missing"));if(missing.Length>0){text.AppendLine("\n\nMISSING REFERENCES");foreach(var item in missing)text.AppendLine("\n• "+Convert.ToString(item));}var conflicts=Data.Items(Data.Get(pack,"conflicts"));if(conflicts.Length>0){text.AppendLine("\n\nCONFLICTS");foreach(var pair in conflicts)text.AppendLine("\n• "+String.Join(" / ",Data.Items(pair).Select(Convert.ToString)));}return text.ToString().Trim();}
 async void LoadPreview(object artifact,string key){if(player!=null){player.Stop();player.Close();player=null;}try{if(artifact==null){preview.Child=T("The team's output will appear here.\n\nTasks keep their source files, checks, and import evidence together.",15,muted);return;}
  string file=Data.Text(artifact,"preview"),type=Data.Text(artifact,"kind");if(new[]{"concept-art","texture","skybox","vfx-source"}.Contains(type)){var bitmap=new BitmapImage();bitmap.BeginInit();bitmap.CacheOption=BitmapCacheOption.OnLoad;bitmap.UriSource=new Uri(file);bitmap.EndInit();preview.Child=new Image{Source=bitmap,Stretch=Stretch.Uniform};}
  else if(new[]{"model","text-to-3d","rigging","animation"}.Contains(type)){preview.Child=T("Preparing native 3D preview…",15,muted);var mesh=await Task.Run(()=>new JavaScriptSerializer{MaxJsonLength=48000000,RecursionLimit=120}.DeserializeObject(File.ReadAllText(file)));if(previewKey==key)preview.Child=MakeViewport(mesh);}
  else{player=new MediaPlayer();player.Open(new Uri(file));var audio=new StackPanel{VerticalAlignment=VerticalAlignment.Center};audio.Children.Add(T("AUDIO REVIEW",12,accent));audio.Children.Add(T("Listen before importing.",23));audio.Children.Add(T(type=="voice"?"Offline character dialogue":"Instrumental music / musical ambience",14,muted));var controls=new StackPanel{Orientation=Orientation.Horizontal};controls.Children.Add(Button("▶ Play",()=>player.Play(),true));controls.Children.Add(Button("Ⅱ Pause",()=>player.Pause()));controls.Children.Add(Button("■ Stop",()=>player.Stop()));audio.Children.Add(controls);preview.Child=audio;}
 }catch(Exception e){preview.Child=T("Preview needs attention:\n"+e.Message,13,muted);}}
 UIElement MakeViewport(object model){
  var viewport=new Viewport3D{ClipToBounds=true};var group=new Model3DGroup();var bounds=Rect3D.Empty;
  foreach(var g in Data.Items(Data.Get(model,"groups"))){var mesh=new MeshGeometry3D();var p=Data.Items(Data.Get(g,"positions"));for(int i=0;i+2<p.Length;i+=3)mesh.Positions.Add(new Point3D(Data.Num(p[i]),Data.Num(p[i+1]),Data.Num(p[i+2])));foreach(var i in Data.Items(Data.Get(g,"indices")))mesh.TriangleIndices.Add(Convert.ToInt32(i));var uv=Data.Items(Data.Get(g,"uv"));for(int i=0;i+1<uv.Length;i+=2)mesh.TextureCoordinates.Add(new Point(Data.Num(uv[i]),Data.Num(uv[i+1])));var color=Data.Items(Data.Get(g,"color"));Brush brush=new SolidColorBrush(Color.FromRgb((byte)(Math.Max(0,Math.Min(1,Data.Num(color[0])))*255),(byte)(Math.Max(0,Math.Min(1,Data.Num(color[1])))*255),(byte)(Math.Max(0,Math.Min(1,Data.Num(color[2])))*255)));string tex=Data.Text(g,"texture");if(File.Exists(tex)){var image=new BitmapImage();image.BeginInit();image.CacheOption=BitmapCacheOption.OnLoad;image.UriSource=new Uri(tex);image.EndInit();brush=new ImageBrush(image);}
   mesh.Freeze();var material=new DiffuseMaterial(brush);var geom=new GeometryModel3D(mesh,material){BackMaterial=material};group.Children.Add(geom);bounds.Union(geom.Bounds);}
  double size=Math.Max(.01,Math.Max(bounds.SizeX,Math.Max(bounds.SizeY,bounds.SizeZ)));var transforms=new Transform3DGroup();transforms.Children.Add(new TranslateTransform3D(-bounds.X-bounds.SizeX/2,-bounds.Y-bounds.SizeY/2,-bounds.Z-bounds.SizeZ/2));var yaw=new AxisAngleRotation3D(new Vector3D(0,1,0),0);var pitch=new AxisAngleRotation3D(new Vector3D(1,0,0),0);transforms.Children.Add(new RotateTransform3D(yaw));transforms.Children.Add(new RotateTransform3D(pitch));group.Transform=transforms;viewport.Children.Add(new ModelVisual3D{Content=group});
  var lights=new Model3DGroup();lights.Children.Add(new AmbientLight(Color.FromRgb(140,140,140)));lights.Children.Add(new DirectionalLight(Colors.White,new Vector3D(-1,-2,-3)));viewport.Children.Add(new ModelVisual3D{Content=lights});double distance=size*2.2;var camera=new PerspectiveCamera(new Point3D(0,size*.2,distance),new Vector3D(0,-size*.2,-distance),new Vector3D(0,1,0),45){NearPlaneDistance=size/1000,FarPlaneDistance=size*100};viewport.Camera=camera;
  var host=new Border{Background=B("#10191C"),Child=viewport,Cursor=Cursors.Hand};Point previous=new Point();bool dragging=false;
  host.MouseLeftButtonDown+=(s,e)=>{dragging=true;previous=e.GetPosition(host);host.CaptureMouse();};host.MouseLeftButtonUp+=(s,e)=>{dragging=false;host.ReleaseMouseCapture();};host.MouseMove+=(s,e)=>{if(!dragging)return;Point now=e.GetPosition(host);yaw.Angle+=(now.X-previous.X)*.5;pitch.Angle=Math.Max(-85,Math.Min(85,pitch.Angle+(now.Y-previous.Y)*.5));previous=now;};host.MouseWheel+=(s,e)=>{distance=Math.Max(size*.3,Math.Min(size*20,distance*(e.Delta>0?.85:1.18)));camera.Position=new Point3D(0,size*.2,distance);camera.LookDirection=new Vector3D(0,-size*.2,-distance);e.Handled=true;};return host;
 }
 async void OnClosing(object sender,System.ComponentModel.CancelEventArgs e){if(closing)return;e.Cancel=true;bool busy=jobs.Any(j=>new[]{"running","queued","importing","cancelling"}.Contains(j.Status));if(busy&&MessageBox.Show(this,"Cancel active production and close the Garage? Completed files and task history will be retained.","Close AI Garage",MessageBoxButton.YesNo,MessageBoxImage.Question)!=MessageBoxResult.Yes)return;
  closing=true;if(timer!=null)timer.Stop();if(player!=null){player.Stop();player.Close();}try{await Api("/shutdown",new{});}catch{}Close();
 }
